var PAL={
  bg:'#0b0e14', card:'#12161f', line:'#1e2530',
  longAccent:'#2ec27e', longSoft:'rgba(46,194,126,0.10)', longHdr:'rgba(46,194,126,0.16)',
  shortAccent:'#f0616d', shortSoft:'rgba(240,97,109,0.10)', shortHdr:'rgba(240,97,109,0.16)',
  ink:'#e6edf3', sub:'#8b98a9', time:'#f3f6fa', amber:'#f2b45a', gold:'#e3c341', blue:'#4a90d9'
};

function tokenLabel(tok, dir){
  if(tok==='TST') return 'PB';
  if(tok==='CONF') return (dir==='long') ? 'Long' : 'Short';
  return tok;
}
function stageEpoch(s, tok){
  if(tok==='BO') return s.ts || s.boBar || null;
  if(tok==='FT') return s.ftBar || null;
  if(tok==='TST') return s.testBar || null;
  if(tok==='CONF') return s.confBar || null;
  if(tok==='GO') return s.goBar || null;
  if(tok==='VOID') return s.voidBar || s.updated || null;
  return null;
}



// ---- (v11.35) UI SCALE ----
// A bigger window on a 2032px monitor still rendered 7px type, because widening a window adds space, it
// does not enlarge anything. `zoom` is the right tool rather than `transform:scale`: it participates in
// layout, so a panel at width:100% still fits its container at any scale instead of overflowing sideways.
var ZOOM_KEY='gpts_zoom_v1', ZOOM_MIN=0.7, ZOOM_MAX=2.2, ZOOM_STEP=0.1;
var UIZOOM=1;
function zoomLoad(){ try{ var z=parseFloat(localStorage.getItem(ZOOM_KEY)); if(isFinite(z)&&z>=ZOOM_MIN&&z<=ZOOM_MAX) UIZOOM=z; }catch(e){} return UIZOOM; }
function zoomSave(){ try{ localStorage.setItem(ZOOM_KEY, String(UIZOOM)); }catch(e){} }
function zoomApply(){
  try{
    if(!PANEL) return;
    PANEL.style.zoom = (UIZOOM===1) ? '' : String(UIZOOM);
    var lbl=document.getElementById('gpts-zoomlbl') || (pipOpen() && PIPWIN.document.getElementById('gpts-zoomlbl'));
    if(lbl) lbl.textContent=Math.round(UIZOOM*100)+'%';
  }catch(e){}
}
function zoomBy(d){
  UIZOOM=Math.round(Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, UIZOOM+d))*100)/100;
  zoomSave(); zoomApply();
}
function zoomReset(){ UIZOOM=1; zoomSave(); zoomApply(); }

// ---- (v11.34) POP OUT — Document Picture-in-Picture ----
// A real always-on-top window that can be dragged to any monitor, rather than a second tab. It is a
// PAGE api, so `@grant none` survives — which matters, because the feed hooks patch window.fetch in page
// context and any @grant would sandbox them and take the tape dark.
//
// THE TRAP: the Atlas tab remains the only thing that captures the feed; the popped-out window is just a
// view of it. Our own code returns early when `document.visibilityState !== 'visible'` (expSetTick), so
// backgrounding Atlas — the entire point of popping out — would silently stop the ladder refreshing while
// the panel kept displaying its last values. `panelVisible()` therefore treats an open PiP window as
// visible, and every visibility check goes through it.
var PIPWIN=null, PIPHOST=null;
function pipOpen(){ return !!(PIPWIN && !PIPWIN.closed); }
function panelVisible(){
  try{ if(pipOpen()) return true; }catch(e){}
  try{ return document.visibilityState==='visible'; }catch(e2){ return true; }
}
function pipSupported(){
  try{ return !!(window.documentPictureInPicture && window.documentPictureInPicture.requestWindow); }catch(e){ return false; }
}
function pipCopyStyles(doc){
  try{
    // the PiP window is a separate document with no stylesheets of its own
    var sheets=document.styleSheets;
    for(var i=0;i<sheets.length;i++){
      var sh=sheets[i], txt='';
      try{ var rules=sh.cssRules||[]; for(var r=0;r<rules.length;r++) txt+=rules[r].cssText; }
      catch(eX){ continue; }               // cross-origin sheet: skip, never throw
      if(!txt) continue;
      var st=doc.createElement('style'); st.textContent=txt; doc.head.appendChild(st);
    }
    var base=doc.createElement('style');
    base.textContent='html,body{margin:0;padding:0;background:'+PAL.bg+';color:'+PAL.ink+';'+
      'font:12px/1.4 Inter,Arial,sans-serif;overflow:auto}'+
      '#gpts-panel{position:static !important;top:auto !important;left:auto !important;right:auto !important;'+
      'width:100% !important;max-width:100% !important;height:auto !important;min-height:100vh;'+
      'border:0 !important;border-radius:0 !important;box-shadow:none !important;z-index:auto !important}'+
      '#gpts-body{cursor:default !important}'+
      '#gpts-grip{display:none !important}';
    doc.head.appendChild(base);
  }catch(e){}
}
function pipToggle(){
  try{
    if(pipOpen()){ try{ PIPWIN.close(); }catch(e){} return; }
    if(!pipSupported()){
      alert('This Chrome does not expose Document Picture-in-Picture.\n\nUse Chrome 116+ , or drag the tab out into its own window.');
      return;
    }
    // (v11.35) Size from the SCREEN, not from the panel's current width. Opening at ~369px on a 2032px
    // monitor was the whole complaint: the window could be dragged bigger, but nothing in it grew.
    var r=PANEL?PANEL.getBoundingClientRect():{width:440,height:700};
    var sw=(screen&&screen.availWidth)||1440, sh=(screen&&screen.availHeight)||900;
    var wantW=Math.round(Math.max(420, Math.min(900, Math.max(r.width||440, sw*0.26))));
    var wantH=Math.round(Math.max(600, Math.min(sh-80, sh*0.88)));
    window.documentPictureInPicture.requestWindow({ width:wantW, height:wantH }).then(function(w){
      PIPWIN=w;
      pipCopyStyles(w.document);
      // remember where the panel came from so it goes back to exactly that spot
      PIPHOST={ parent:PANEL.parentNode, next:PANEL.nextSibling };
      w.document.body.appendChild(PANEL);
      w.addEventListener('pagehide', pipRestore);
      try{ zoomApply(); }catch(eZ){}
      try{ render(); }catch(e2){}
    }).catch(function(err){
      // requestWindow rejects without a user gesture, and that is the usual cause
      try{ console.warn('[GPTS] pop-out refused:', err && err.message); }catch(e3){}
    });
  }catch(e){}
}
function pipRestore(){
  try{
    if(PANEL && PIPHOST && PIPHOST.parent){
      if(PIPHOST.next && PIPHOST.next.parentNode===PIPHOST.parent) PIPHOST.parent.insertBefore(PANEL, PIPHOST.next);
      else PIPHOST.parent.appendChild(PANEL);
      // the inline geometry the panel had before it was moved is restored by restorePos/restoreSize
      PANEL.style.position='fixed';
      try{ restorePos(); restoreSize(); zoomApply(); }catch(e1){}
    }
  }catch(e){}
  PIPWIN=null; PIPHOST=null;
  try{ render(); }catch(e2){}
}
function buildPanel(){
  if(document.getElementById('gpts-panel')) return;
  PANEL=document.createElement('div');
  PANEL.id='gpts-panel';
  css(PANEL,{position:'fixed', top:'60px', left:'', right:'12px', width:'440px',
    background:PAL.bg, color:PAL.ink, font:'12px/1.4 Inter,Arial,sans-serif',
    border:'1px solid '+PAL.line, borderRadius:'10px', zIndex:'999999',
    boxShadow:'0 8px 28px rgba(0,0,0,0.6)', userSelect:'none', overflow:'visible'});
  var hdr=document.createElement('div');
  hdr.id='gpts-hdr';
  css(hdr,{padding:'5px 11px', background:'#0f131b', borderBottom:'1px solid '+PAL.line,
    borderRadius:'10px 10px 0 0', cursor:'move', display:'flex',
    justifyContent:'space-between', alignItems:'center'});
  var ttl=document.createElement('span');
  ttl.textContent='Tapereader';
  css(ttl,{color:PAL.ink, fontSize:'12px', fontWeight:'800', letterSpacing:'0.4px',
    borderLeft:'3px solid '+PAL.blue, paddingLeft:'7px', whiteSpace:'nowrap'});
  hdr.appendChild(ttl);
  var right=document.createElement('span');
  css(right,{display:'flex', alignItems:'center', gap:'6px'});
  var grade=document.createElement('span');
  grade.id='gpts-grade';
  grade.title='Setup grade for the in-play direction.';
  css(grade,{fontSize:'11px', fontWeight:'800', padding:'1px 7px', borderRadius:'6px', display:'none'});
  right.appendChild(grade);
  var fresh=document.createElement('span');
  fresh.id='gpts-fresh';
  fresh.title='Feed freshness.';
  css(fresh,{fontSize:'9px', fontWeight:'700'});
  right.appendChild(fresh);
  var handle=document.createElement('span');
  handle.id='gpts-draghandle';
  handle.innerHTML='&#10303;';
  handle.title='Drag to move (you can also drag from any empty area of the panel).';
  css(handle,{cursor:'grab', color:PAL.sub, fontSize:'14px', lineHeight:'1', padding:'0 2px'});
  right.appendChild(handle);
  var zOut=document.createElement('span');
  zOut.id='gpts-zoomout'; zOut.textContent='\u2212';
  zOut.title='Make the panel smaller. Scales the whole panel, so it stays readable when popped out on a large monitor.';
  css(zOut,{cursor:'pointer', color:PAL.sub, fontSize:'13px', lineHeight:'1', padding:'0 3px', fontWeight:'800'});
  zOut.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  zOut.addEventListener('click', function(e){ e.stopPropagation(); zoomBy(-ZOOM_STEP); });
  right.appendChild(zOut);
  var zLbl=document.createElement('span');
  zLbl.id='gpts-zoomlbl'; zLbl.textContent='100%';
  zLbl.title='Panel scale. Click to reset to 100%.';
  css(zLbl,{cursor:'pointer', color:PAL.sub, fontSize:'8.5px', fontWeight:'700', minWidth:'26px', textAlign:'center'});
  zLbl.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  zLbl.addEventListener('click', function(e){ e.stopPropagation(); zoomReset(); });
  right.appendChild(zLbl);
  var zIn=document.createElement('span');
  zIn.id='gpts-zoomin'; zIn.textContent='+';
  zIn.title='Make the panel bigger.';
  css(zIn,{cursor:'pointer', color:PAL.sub, fontSize:'13px', lineHeight:'1', padding:'0 3px', fontWeight:'800'});
  zIn.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  zIn.addEventListener('click', function(e){ e.stopPropagation(); zoomBy(ZOOM_STEP); });
  right.appendChild(zIn);
  var pip=document.createElement('span');
  pip.id='gpts-pip';
  pip.innerHTML='&#8599;';
  pip.title='Pop the panel out into its own always-on-top window, which you can drag to another monitor. The Atlas tab must stay open — it is what captures the feed — but it no longer has to be the tab you are looking at.';
  css(pip,{cursor:'pointer', color:PAL.sub, fontSize:'14px', lineHeight:'1', padding:'0 2px'});
  pip.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  pip.addEventListener('click', function(e){ e.stopPropagation(); pipToggle(); });
  right.appendChild(pip);
  var gear=document.createElement('span');
  gear.id='gpts-gear';
  gear.innerHTML='&#9881;';
  gear.title='Config: open BO Pullback settings (node thresh, follow-through, signal type, trend).';
  css(gear,{cursor:'pointer', color:PAL.sub, fontSize:'15px', lineHeight:'1', padding:'0 2px'});
  gear.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  gear.addEventListener('click', function(e){ e.stopPropagation(); toggleCfg(); });
  right.appendChild(gear);
  var clr=document.createElement('span');
  clr.id='gpts-clear';
  clr.textContent='Clear';
  clr.title='Erase every tracked setups and reset the state machine.';
  css(clr,{cursor:'pointer', color:PAL.amber, fontWeight:'600', fontSize:'10px',
    padding:'1px 7px', border:'1px solid '+PAL.line, borderRadius:'20px'});
  clr.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  clr.addEventListener('click', function(e){ e.stopPropagation(); clearSignalsAll(); });
  right.appendChild(clr);
  hdr.appendChild(right);
  PANEL.appendChild(hdr);

  elCfg=document.createElement('div');
  elCfg.id='gpts-cfg';
  css(elCfg,{display:'none', position:'absolute', top:'36px', right:'8px', width:'240px',
    background:PAL.card, border:'1px solid '+PAL.line, borderRadius:'8px', zIndex:'1000001',
    boxShadow:'0 6px 20px rgba(0,0,0,0.6)', padding:'6px 8px 8px 8px'});
  PANEL.appendChild(elCfg);

  elBody=document.createElement('div');
  elBody.id='gpts-body';
  css(elBody,{padding:'9px 10px', cursor:'move', position:'relative'});
  PANEL.appendChild(elBody);

  // (v10.25) 5-step methodology popover (created once, positioned near the clicked icon)
  var pop=document.createElement('div');
  pop.id='gpts-step-pop';
  pop.innerHTML='<span class="gs-x">\u2715</span><div id="gpts-step-pop-body"></div>';
  pop.addEventListener('mousedown', function(e){ e.stopPropagation(); });   // don't drag the panel
  elBody.appendChild(pop);
  pop.querySelector('.gs-x').addEventListener('click', function(e){ e.stopPropagation(); closeStepPop(); });

  var grip=document.createElement('div');
  grip.id='gpts-grip';
  css(grip,{position:'absolute', right:'0', bottom:'0', width:'16px', height:'16px',
    cursor:'nwse-resize', background:'linear-gradient(135deg, transparent 50%, #3a4150 50%, #3a4150 60%, transparent 60%, transparent 70%, #3a4150 70%, #3a4150 80%, transparent 80%)'});
  PANEL.appendChild(grip);

  document.body.appendChild(PANEL);
  restorePos();
  restoreSize();
  zoomLoad(); zoomApply();
  makeDraggable([hdr, elBody]);   // drag from the header OR anywhere in the body
  makeResizable(grip);
}

function toggleCfg(){
  if(!elCfg) return;
  if(elCfg.style.display==='none'){ renderCfg(); elCfg.style.display='block'; }
  else { elCfg.style.display='none'; }
}

// Full-body drag: you can grab ANY empty area of the panel to move it, not
// just the top bar. A press-and-move is treated as a drag; a plain click or
// text-selection still works because we ignore mousedowns that land on
// interactive elements and only start dragging once the pointer actually moves.
function isInteractiveTarget(t){
  while(t && t!==PANEL){
    var tag=(t.tagName||'').toLowerCase();
    if(tag==='input'||tag==='select'||tag==='textarea'||tag==='button'||tag==='a') return true;
    if(t.id==='gpts-gear'||t.id==='gpts-clear'||t.id==='gpts-cfg'||t.id==='gpts-grip') return true;
    if(t.classList && (t.classList.contains('gpts-clr-sym'))) return true;
    if(t.classList && (t.classList.contains('gpts-act') || t.classList.contains('gpts-brief'))) return true;   // (v10.49 H) one-tap controls, never a drag
    t=t.parentNode;
  }
  return false;
}
function makeDraggable(dragEls){
  if(!Array.isArray(dragEls)) dragEls=[dragEls];
  var dragging=false, armed=false, sx=0, sy=0, ox=0, oy=0;
  var THRESH=4; // px of movement before a press becomes a drag (lets clicks/selection through)
  function onDown(e){
    if(e.button!==0) return;                 // left button only
    if(isInteractiveTarget(e.target)) return; // let buttons/inputs/links work
    armed=true; dragging=false; sx=e.clientX; sy=e.clientY;
    var r=PANEL.getBoundingClientRect(); ox=r.left; oy=r.top;
  }
  dragEls.forEach(function(el){ if(el) el.addEventListener('mousedown', onDown); });
  document.addEventListener('mousemove', function(e){
    if(!armed) return;
    if(!dragging){
      if(Math.abs(e.clientX-sx)<THRESH && Math.abs(e.clientY-sy)<THRESH) return;
      dragging=true;
      PANEL.style.right=''; PANEL.style.left=ox+'px'; PANEL.style.top=oy+'px';
    }
    var nx=ox+(e.clientX-sx), ny=oy+(e.clientY-sy);
    PANEL.style.left=nx+'px'; PANEL.style.top=ny+'px';
    e.preventDefault();
  });
  document.addEventListener('mouseup', function(){
    armed=false;
    if(!dragging) return; dragging=false;
    try{ localStorage.setItem(POS_KEY, JSON.stringify({left:PANEL.style.left, top:PANEL.style.top})); }catch(e){}
  });
}
function makeResizable(grip){
  var rz=false, sx=0, sy=0, ow=0, oh=0;
  grip.addEventListener('mousedown', function(e){
    rz=true; sx=e.clientX; sy=e.clientY;
    var r=PANEL.getBoundingClientRect(); ow=r.width; oh=r.height;
    e.preventDefault(); e.stopPropagation();
  });
  document.addEventListener('mousemove', function(e){
    if(!rz) return;
    var nw=ow+(e.clientX-sx), nh=oh+(e.clientY-sy);
    if(nw<240) nw=240; if(nw>560) nw=560;
    if(nh<160) nh=160; if(nh>900) nh=900;
    PANEL.style.width=nw+'px'; PANEL.style.height=nh+'px';
    render();
  });
  document.addEventListener('mouseup', function(){
    if(!rz) return; rz=false;
    try{ localStorage.setItem(SIZE_KEY, JSON.stringify({w:PANEL.style.width, h:PANEL.style.height})); }catch(e){}
  });
}
function restorePos(){
  try{ var p=JSON.parse(localStorage.getItem(POS_KEY)||'null');
    if(p&&p.left){ PANEL.style.right=''; PANEL.style.left=p.left; PANEL.style.top=p.top; }
  }catch(e){}
}
function restoreSize(){
  try{ var s=JSON.parse(localStorage.getItem(SIZE_KEY)||'null');
    if(s&&s.w){ PANEL.style.width=s.w; if(s.h) PANEL.style.height=s.h; }
    // (v10.41) ONE-TIME 2-COLUMN MIGRATION: the dashboard is now two columns
    // side by side, which needs ~680px. A saved (or default) width from the
    // single-column era leaves the columns stacked and the user seeing "no
    // change". Bump once, remember we did, keep any later user resize sacred.
    // (v10.44) ONE-TIME SINGLE-COLUMN MIGRATION: back to one column; a 690px panel
    // wastes width. Shrink once to 440px, remember, keep later user resizes sacred.
    var did=null; try{ did=localStorage.getItem('gpts_1col_migr_v44'); }catch(e2){}
    var wNow=parseInt((PANEL.style.width||'0'),10)||0;
    if(!did && wNow>520){
      PANEL.style.width='440px';
      try{ localStorage.setItem('gpts_1col_migr_v44','1');
           localStorage.setItem(SIZE_KEY, JSON.stringify({w:'440px', h:PANEL.style.height||''})); }catch(e3){}
    } else if(!did){ try{ localStorage.setItem('gpts_1col_migr_v44','1'); }catch(e4){} }
  }catch(e){}
}

function fmtNum(x){ return (Math.round(mul(x,100))/100).toString(); }
// (v11.0.1) a futures LEVEL is spoken on the instrument's tick — ES/MES/NQ/MNQ trade in 0.25
// points, so 7716.36 is not a price anyone can trade; 7716.25 is.
var FUT_TICK={ ES:0.25, NQ:0.25 };
// (v11.60) DOLLARS PER INDEX POINT. Verified against CME / NinjaTrader contract specs 2026-08-22, not
// assumed — a wrong multiplier puts a wrong dollar figure on the face under the panel's own name:
//   ES $50/pt (tick 0.25 = $12.50) · MES $5 · NQ $20 · MNQ $2   (micros are 1/10 of the E-mini)
// Keyed by the CHART symbol, never the family: ES and MES share a family and differ by 10x.
var FUT_MULT={ ES:50, MES:5, NQ:20, MNQ:2 };
function futMult(){ try{ var c=(typeof FUTMODE!=='undefined'&&FUTMODE)?FUTMODE.chart:null; return (c&&FUT_MULT[c])||null; }catch(e){ return null; } }
// (v11.63) BIG DOLLARS GET ABBREVIATED. `usd()` printed the hedging flow as "$213,827,434/pt" — seventeen
// characters of false precision that blew line 1 apart. Nobody reads a flow figure to the dollar; they read
// its ORDER. Contract sizes stay exact ($1,736 is meaningful to the dollar), flows do not.
function usdBig(v){
  try{
    if(typeof v!=='number'||!isFinite(v)) return null;
    var a=Math.abs(v);
    if(a>=1e9) return '$'+(a/1e9).toFixed(a>=1e10?0:1)+'B';
    if(a>=1e6) return '$'+Math.round(a/1e6)+'M';
    if(a>=1e4) return '$'+Math.round(a/1e3)+'K';
    return usd(v);
  }catch(e){ return null; }
}
// (v11.66) THE SAME NUMBER, BREATHING. "$214M/pt" is nine glyphs with no gap in them, and on a chip at
// 8px it reads as one long token the eye has to parse rather than three facts it can take at a glance.
// The value is identical — only the spacing changes, and only on the chip. `usdBig` stays tight because
// it is also used inside sentences, where a space before the unit would look like a typo.
function usdBigSp(v){
  try{ var t=usdBig(v); if(!t) return t; return t.replace(/([0-9])([KMB])$/, '$1 $2'); }catch(e){ return usdBig(v); }
}
// $1,737 — whole dollars. Cents on a four-figure number are noise on a face with no space.
function usd(v){
  try{ if(typeof v!=='number'||!isFinite(v)) return null;
    // ⚠ ROUND THROUGH CENTS FIRST. 34.73*50 is 1736.4999999999998 in floating point, and rounding that
    // straight to dollars yields $1,736 for a move genuinely worth $1,736.50 — a one-dollar error on the
    // face, from arithmetic that looks exact. Cents first, then dollars.
    var cents=Math.round(Math.abs(v)*100)/100;
    return '$'+Math.round(cents).toString().replace(/\B(?=(\d{3})+(?!\d))/g,',');
  }catch(e){ return null; }
}
function futTick(){ try{ var f=(typeof FUTMODE!=='undefined'&&FUTMODE)?FUTMODE.fam:null; return (f && FUT_TICK[f])||null; }catch(e){ return null; } }
function fmtFut(x){
  var tk=futTick();
  if(tk){ var r=Math.round(x/tk)*tk; return (Math.round(mul(r,100))/100).toString(); }
  return (Math.round(mul(x,100))/100).toString();
}

// ============================================================================
// (v10.55 PART E) FUTURES MODE — the chart may be a FUTURE, and then every level
// the panel draws must be spoken in that future's points.
//
// The options tape only exists for the CASH underlyings (SPY / QQQ). So the panel
// keeps computing everything in SPY/QQQ strikes — the recording, the learning and
// the whole feature registry are UNCHANGED — and converts only what it DISPLAYS,
// through a live ratio r = futPrice / underlyingPrice (EMA-smoothed).
//   ES,MES -> SPY tape · NQ,MNQ -> QQQ tape · SPY -> SPY · QQQ -> QQQ
//   anything else -> "No options tape for <SYM> — levels unavailable". NEVER an
//   invented level: a GC or CL chart has no dealer-exposure map here, full stop.
// When the fut price cannot be read we fall back to the last good ratio, then to
// the constant, and EVERY converted number is marked with '≈' so the difference
// between a measured conversion and an assumed one is visible on the face.
// ============================================================================
var FUTCFG_KEY='gpts_futcfg_v1';
var FUTCFG={ mode:'auto' };                    // auto | SPY | ES | NQ  (⚙ override)
function futCfgLoad(){
  try{ var o=JSON.parse(localStorage.getItem(FUTCFG_KEY)||'null');
    if(o && (o.mode==='auto'||o.mode==='SPY'||o.mode==='ES'||o.mode==='NQ')) FUTCFG.mode=o.mode; }catch(e){}
  return FUTCFG;
}
function futCfgSave(){ try{ localStorage.setItem(FUTCFG_KEY, JSON.stringify(FUTCFG)); }catch(e){} }
var NQ_RATIO = 41.36;                          // last-known QQQ→NQ constant (fallback only)
var FUT_FAMILY={ ES:'ES', MES:'ES', NQ:'NQ', MNQ:'NQ' };
var FUT_UNDERLYING={ ES:'SPY', MES:'SPY', SPY:'SPY', NQ:'QQQ', MNQ:'QQQ', QQQ:'QQQ' };
var FUT_CONST={ ES:ES_RATIO, NQ:NQ_RATIO };
var FUT_EMA_A=0.25;                            // ratio smoothing
var FUTR={ ES:{ ema:null, last:null, t:0 }, NQ:{ ema:null, last:null, t:0 } };
var FUTMODE={ chart:'SPY', fam:null, underlying:'SPY', r:1, live:false, approx:false,
              ok:true, msg:null, futPx:null, undPx:null, source:'default', forced:false };
// PURE: pull a chart symbol out of a title / header string. 'ES1 $7768.75' -> 'ES'.
var FUT_KNOWN=['MES','MNQ','ES','NQ','SPY','QQQ'];
function chartSymFromText(txt){
  if(!txt) return null;
  var t=String(txt).toUpperCase();
  for(var i=0;i<FUT_KNOWN.length;i++){
    var s=FUT_KNOWN[i];
    if(new RegExp('(^|[^A-Z])'+s+'[0-9!]?([^A-Z0-9]|$)').test(t)) return s;
  }
  var m=t.match(/(^|[^A-Z])([A-Z]{1,4})[0-9!]?\s*\$/);   // "GC1 $2465.10" — a symbol we cannot map
  return m?m[2]:null;
}
// PURE: the dollar price out of the same string.
function chartPxFromText(txt){
  if(!txt) return null;
  var m=String(txt).match(/\$\s*([\d,]+\.?\d*)/);
  if(!m) return null;
  var v=parseFloat(m[1].replace(/,/g,''));
  return isFinite(v)?v:null;
}
// PURE: r update with EMA smoothing + the honest fallback chain.
function futRatioStep(st, futPx, undPx, fam){
  st=st||{ ema:null, last:null, t:0 };
  if(typeof futPx==='number' && typeof undPx==='number' && futPx>0 && undPx>0){
    var r=futPx/undPx;
    if(isFinite(r) && r>0){
      st.ema=(st.ema==null)?r:(st.ema+mul(FUT_EMA_A,(r-st.ema)));
      st.last=st.ema; st.t=Date.now();
      return { r:st.ema, live:true, approx:false, src:'live' };
    }
  }
  if(st.last!=null) return { r:st.last, live:false, approx:true, src:'last-good' };
  return { r:(FUT_CONST[fam]!=null?FUT_CONST[fam]:1), live:false, approx:true, src:'const' };
}
// The underlying's own price, straight off the feed (levels[last].s) when we have one.
function feedUnderlyingPx(sym){
  try{
    var f=LASTFEED[sym];
    var lv=(f && f.j && f.j.levels)||null;
    if(lv && lv.length){ var s=lv[lv.length-1].s; if(typeof s==='number' && s>0) return s; }
  }catch(e){}
  try{ var p=(STATE[sym]||{}).price; if(typeof p==='number' && p>0) return p; }catch(e2){}
  return null;
}
// What is on the chart right now? title first, then the trinity header ticker.
function futDetect(){
  var sym=null, px=null, src='none';
  try{ var t=document.title; var s=chartSymFromText(t); if(s){ sym=s; px=chartPxFromText(t); src='title'; } }catch(e){}
  if(!sym || px==null){
    try{
      var hs=readTrinityHeaders();
      if(hs){ for(var k in hs){ if(!hs.hasOwnProperty(k)) continue;
        var kk=chartSymFromText(k);
        if(kk && (!sym || kk===sym)){ if(!sym){ sym=kk; src='header'; } if(px==null && hs[k] && typeof hs[k].px==='number'){ px=hs[k].px; if(src==='none') src='header'; } } } }
    }catch(e2){}
  }
  return { sym:sym, px:px, src:src };
}
// Recomputed each render. Never throws; a failure degrades to plain SPY mode.
function futModeCompute(){
  var out={ chart:'SPY', fam:null, underlying:'SPY', r:1, live:false, approx:false,
            ok:true, msg:null, futPx:null, undPx:null, source:'default', forced:false };
  try{
    var det=futDetect();
    var chart=det.sym||'SPY';
    if(FUTCFG.mode && FUTCFG.mode!=='auto'){ chart=FUTCFG.mode; out.forced=true; }
    out.chart=chart; out.source=out.forced?'forced':det.src;
    out.futPx=(det.sym===chart)?det.px:null;
    var und=FUT_UNDERLYING[chart]||null;
    if(!und){
      out.ok=false; out.underlying='SPY'; out.r=1;
      out.msg='No options tape for '+chart+' — levels unavailable';
      return out;
    }
    out.underlying=und;
    var fam=FUT_FAMILY[chart]||null;
    out.fam=fam;
    if(!fam){ out.r=1; out.live=true; return out; }          // a cash chart: no conversion at all
    var undPx=feedUnderlyingPx(und);
    out.undPx=undPx;
    var step=futRatioStep(FUTR[fam], out.futPx, undPx, fam);
    FUTR[fam]=FUTR[fam]||{ema:null,last:null,t:0};
    out.r=step.r; out.live=step.live; out.approx=step.approx; out.ratioSrc=step.src;
  }catch(e){}
  return out;
}
function futModeRefresh(){ try{ FUTMODE=futModeCompute(); }catch(e){} return FUTMODE; }
function futMode(){ return FUTMODE; }
// The symbol whose tape everything is computed from RIGHT NOW (PART G: QQQ parity).
function activeSym(){
  try{ return (FUTMODE && FUTMODE.underlying==='QQQ') ? 'QQQ' : 'SPY'; }catch(e){ return 'SPY'; }
}
// (v11.75) ① FRAME PRICES ARE WHOLE POINTS ON A FUTURES CHART. `7730.48` and `7661.02` are not prices
// anyone can trade — ES moves in quarter points, so those two decimals are noise wearing precision. The
// user's call: round to the nearest whole point and keep it simple, rather than snapping to the 0.25 tick.
// ⚠ SCOPED TO THIS SECTION ONLY, and only when the chart IS a future. `dispNum` stays exactly as it was
// everywhere else, and on a SPY chart (~764) whole points would be far too coarse to mean anything.
// (v11.79) the ES->SPX inverse, so a hover can quote the index level beside the futures one. The band is
// computed in CHART (ES) space; the strikes behind it are SPX. Both are useful and they are not the same
// number — the basis was +17.65 points on 2026-08-23.
function ifDispScale(){ try{ var L=ifLadder(activeSym()); return (L && !L.err && L.dispScale>0) ? L.dispScale : 0; }catch(e){ return 0; } }
function frameNum(x){
  if(x==null) return '\u2013';
  try{ if(dispIsFut()) return String(Math.round(x)); }catch(e){}
  return dispNum(x);
}
function dispIsFut(){ try{ return !!(FUTMODE && FUTMODE.fam && FUTMODE.ok); }catch(e){ return false; } }
function dispR(){ try{ return (dispIsFut() && FUTMODE.r>0) ? FUTMODE.r : 1; }catch(e){ return 1; } }
// A LEVEL as the user should read it on THIS chart. In SPY/QQQ mode this is exactly
// fmtNum, so nothing about the cash panel changes.
// (v11.0 audit) PARKED — no live caller; kept because test_futures_mode.js pins it.
function dispVal(x){ if(x==null) return null; return dispIsFut()? mul(x, dispR()) : x; }
function futMark(){ return (dispIsFut() && FUTMODE.approx) ? '≈' : ''; }
function fmtLvl(x){
  if(x==null) return '–';
  if(!dispIsFut()) return fmtNum(x);
  return futMark()+fmtFut(mul(x, dispR()));
}
// A DISTANCE / width in the displayed instrument's points (0.50 SPY -> 5.0 ES).
function fmtSpan(x){
  if(x==null) return '–';
  if(!dispIsFut()) return fmtNum(x);
  return futMark()+fmtFut(mul(x, dispR()));
}
// PURE: futures chart candles -> underlying candles, so trendVerdict / in-play /
// drift / R:R keep working on the cash scale while the chart shows a future.
function futCandlesToUnderlying(raw, r){
  if(!raw || !raw.length || !(r>0)) return null;
  var out=[];
  for(var i=0;i<raw.length;i++){
    var x=raw[i]; if(!x || typeof x.time!=='number') continue;
    out.push({ time:x.time, open:x.open/r, high:x.high/r, low:x.low/r, close:x.close/r });
  }
  return out.length?out:null;
}
// The raw candle array for a symbol, reconstructed from the futures chart when that
// is what the page is showing.
function futRawCandles(sym){
  var raw=null;
  try{ raw=readFiberCandles(sym); }catch(e){}
  if(raw && raw.length) return raw;
  try{
    if(!dispIsFut()) return null;
    var r=dispR(); if(!(r>0)) return null;
    var names=[FUTMODE.chart, FUTMODE.chart+'1', FUTMODE.chart+'1!'];
    for(var i=0;i<names.length;i++){
      var fr=null; try{ fr=readFiberCandles(names[i]); }catch(e2){}
      if(fr && fr.length) return futCandlesToUnderlying(fr, r);
    }
  }catch(e3){}
  return null;
}
// The underlying price implied by the futures print (used only when the cash feed
// has nothing — the feed's own price always wins).
function futUnderlyingPx(){
  try{
    if(!dispIsFut() || FUTMODE.futPx==null) return null;
    var r=dispR(); if(!(r>0)) return null;
    return FUTMODE.futPx/r;
  }catch(e){ return null; }
}
// The footer line: 'ES/SPY 10.071 (live)' / '(≈ const)'.
function futRatioText(){
  try{
    if(!dispIsFut()) return '';
    var lab=FUTMODE.fam+'/'+FUTMODE.underlying+' '+(Math.round(mul(FUTMODE.r,1000))/1000);
    var tag=FUTMODE.live?'(live)':('(≈ '+((FUTMODE.ratioSrc==='last-good')?'last':'const')+')');
    return lab+' '+tag;
  }catch(e){ return ''; }
}
function futUnavailableHtml(){
  var msg=(FUTMODE&&FUTMODE.msg)||'No options tape — levels unavailable';
  // (v11.4.2) if Skylit IS serving a book for this instrument, say the honest thing: the tape exists,
  // this panel is mapped to SPY/QQQ only, and nothing about it is being read or recorded.
  try{ var cs=(FUTMODE&&FUTMODE.chart)||null;
    if(cs && SYM_SEEN[cs] && SYM_SEEN[cs].n>0) msg=cs+' has a Skylit options tape, but this panel is mapped to SPY/QQQ only — nothing here is read or recorded for '+cs+'.'; }catch(e){}
  return '<div title="The options dealer-exposure tape only exists for SPY and QQQ (and the ES/NQ futures that track them). For any other instrument this panel has no map, and it will not invent one." '+
    'style="border-left:2px solid '+PAL.amber+';background:'+PAL.card+';border-radius:0 8px 8px 0;padding:6px 9px;margin:3px 0;font-size:10px;color:'+PAL.amber+';font-weight:700">'+
    msg+'</div>';
}

// ============================================================================
// 5-STEP INFO ICONS (v10.25) — the Skylit 'How to Read & Use Heatseeker' method,
// quoted faithfully behind small circular ①②③④⑤ icons. CLICK opens a popover (text
// is long). Step 2 = EOD ONLY (day-trading tool). Step 4 keeps the doc rule of
// thumb verbatim even though our impl uses the soft booster.
// ============================================================================
var STEP_TEXT = {
  1:{t:'Step 1 — Identify the Magnets', h:
    '<div class="gs-sub">Concept of Magnets</div>'+
    '<p>Every node acts like a <b>magnet</b>. Price is attracted to these zones due to dealer positioning \u2014 yet the same areas can act as <b>walls that repel</b> price and create reversals.</p>'+
    '<ul><li><b>Larger node values = stronger magnets.</b></li><li>The <b>closer price drifts</b>, the <b>stronger the pull</b>.</li></ul>'+
    '<div class="gs-sub">Magnetic Behavior</div>'+
    '<ul><li>Farther from a high-value node \u2192 pull <b>weakens</b>.</li><li>Approaching one \u2192 pull <b>strengthens</b>.</li><li>Direct interaction can cause a <b>deflection/repulsion</b>.</li></ul>'},
  2:{t:'Step 2 — Spot the King Node', h:
    '<p>The <b>King Node</b> is the most influential node \u2014 where Market Makers prefer to <b>settle price</b> by the <b>end of day (EOD)</b>. This is a day-trading tool, so the King is your <b>EOD settlement anchor</b>.</p>'+
    '<div class="gs-sub">How to Use It</div>'+
    '<ul><li>Your <b>primary destination target</b> for the session.</li><li>Mark it as your <b>EOD anchor</b>.</li><li>Watch early-day <b>drive-offs</b> or late-day <b>pinning</b>.</li></ul>'},
  3:{t:'Step 3 — Define the Range', h:
    '<p>Ranges provide some of the <b>highest-probability setups</b> and best risk-to-reward.</p>'+
    '<ul><li>Find where price <b>consistently reverses</b> \u2014 these are the boundaries.</li><li>At the <b>extreme end</b>, <b>fade the edge</b> \u2014 don\u2019t chase.</li><li>Avoid <b>midpoints</b> \u2014 poor R:R, uncertain direction.</li></ul>'},
  4:{t:'Step 4 — Watch Gatekeeper Nodes', h:
    '<p><b>Gatekeeper Nodes</b> are defensive levels that often <b>block price</b> from reaching the King Node. They act as <b>strong rejection zones</b>, and failed tests can <b>trigger trend shifts</b>.</p>'+
    '<div class="gs-sub">How to Read Them</div>'+
    '<ul><li>Rejection \u2192 potential <b>map reshuffling</b> or <b>directional change</b>.</li><li><b>Early-day rejections</b> often mark <b>powerful reversals</b>.</li><li>Align <b>SPX, SPY, QQQ</b> \u2014 confluence increases probability; mixed lowers it.</li></ul>'+
    '<div class="gs-sub">Rule of thumb</div><p>SPX, SPY, and QQQ must agree \u2014 if one diverges, stand aside.</p>'},
  5:{t:'Step 5 — Map the Flow', h:
    '<p>Heatseeker updates <b>dynamically</b> as dealer positioning shifts. Each <b>reshuffle</b> is a change in Market Maker risk and can reshape your bias.</p>'+
    '<div class="gs-sub">Watch for</div>'+
    '<ul><li><b>Accumulation (Acm):</b> dealers building \u2192 <b>stronger</b> magnets.</li><li><b>Dissipation (Diss):</b> dealers closing \u2192 <b>weakening</b> nodes.</li><li><b>Reshuffling:</b> rapid changes \u2192 new structure.</li></ul>'+
    '<p>By playing <b>direct deflections off key nodes</b>, you\u2019re trading <b>ahead of the reshuffle</b>.</p>'+
    '<div class="gs-sub">Our rule</div><p>Accumulation only <b>attracts</b> price to a node. We make <b>no</b> deflect/break call \u2014 the breakout tracker resolves the outcome (broke \u2191 / broke \u2193 / held / false break).</p>'}
};
// small circular icon; data-gstep drives the delegated click handler in the panel.
// (v11.0 audit) PARKED — no live caller; kept because PARKED kingBlock chain pins it.
function stepIcon(n, extraStyle){
  return '<span class="gs-ico" data-gstep="'+n+'" title="Step '+n+' \u2014 click for the method" '+
    'style="width:16px;height:16px;border-radius:50%;border:1px solid '+PAL.sub+';color:'+PAL.sub+';'+
    'font-size:9.5px;font-weight:800;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;'+(extraStyle||'')+'">'+n+'</span>';
}
var STEP_POP_OPEN = 0;   // which step's popover is open (0 = none)
function ensureStepPop(){
  if(!elBody) return;
  if(elBody.querySelector('#gpts-step-pop')) return;   // still there
  var pop=document.createElement('div');
  pop.id='gpts-step-pop';
  pop.innerHTML='<span class="gs-x">\u2715</span><div id="gpts-step-pop-body"></div>';
  pop.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  elBody.appendChild(pop);
  pop.querySelector('.gs-x').addEventListener('click', function(e){ e.stopPropagation(); closeStepPop(); });
  STEP_POP_OPEN=0;
}
function closeStepPop(){
  STEP_POP_OPEN=0;
  var pop=document.getElementById('gpts-step-pop');
  if(pop) pop.classList.remove('gs-show');
  var ons=document.querySelectorAll('#gpts-panel .gs-ico.gs-on');
  for(var i=0;i<ons.length;i++) ons[i].classList.remove('gs-on');
}
function openStepPop(n, iconEl){
  var pop=document.getElementById('gpts-step-pop'), body=document.getElementById('gpts-step-pop-body');
  if(!pop||!body||!STEP_TEXT[n]) return;
  if(STEP_POP_OPEN===n){ closeStepPop(); return; }   // toggle off
  closeStepPop();
  STEP_POP_OPEN=n;
  body.innerHTML='<div class="gs-ttl">'+STEP_TEXT[n].t+'</div>'+STEP_TEXT[n].h;
  // position just under the clicked icon (relative to elBody)
  if(iconEl && elBody){
    var br=elBody.getBoundingClientRect(), ir=iconEl.getBoundingClientRect();
    pop.style.top=(ir.bottom-br.top+6)+'px';
  } else { pop.style.top='40px'; }
  pop.classList.add('gs-show');
  if(iconEl) iconEl.classList.add('gs-on');
}
// delegated: wire every .gs-ico in the body (called after each render)
function wireStepIcons(){
  if(!elBody) return;
  var icos=elBody.querySelectorAll('.gs-ico');
  for(var i=0;i<icos.length;i++){
    (function(el){
      el.addEventListener('mousedown', function(e){ e.stopPropagation(); });   // don't start a panel drag
      el.addEventListener('click', function(e){ e.stopPropagation(); openStepPop(parseInt(el.getAttribute('data-gstep'),10), el); });
    })(icos[i]);
  }
}

